#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "lu.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -----------------------------------------------------------------------------
// Array initialization: translate Polybench init_array() into a Halide pipeline
// -----------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // We map the original C array A[i][j] to Halide buffer A(j, i):
    //   - i is the row index  -> second dimension (y)
    //   - j is the column index -> first dimension (x)

    Var i("i"), j("j");
    Func A0("A0"), B("B");

    // First, generate the lower-triangular matrix used as in the C code:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Note: for 0 <= j < n, (-j % n) == -j, so we can drop the % n.
    // We fold all this into a single expression:

    Expr one   = cast<num_t>(1);
    Expr zero  = cast<num_t>(0);
    Expr n_val = cast<num_t>(n);

    A0(j, i) = select(
        j <= i,
        // On or below the diagonal
        select(i == j,
               // Diagonal element
               one,
               // Strictly lower triangular part
               cast<num_t>(-j) / n_val + one),
        // Above the diagonal
        zero);

    // Now make the matrix positive semi-definite by computing:
    //
    // B[r][s] = sum_t A[r][t] * A[s][t];
    //
    // and then copying B back into A. In terms of our mapping:
    // B(r, s) in C  -> B(j, i) in Halide
    // A[r][t]       -> A0(t, r) -> A0(t, i)
    // A[s][t]       -> A0(t, s) -> A0(t, j)
    //
    // So:
    //   B(j, i) = sum_{t=0..n-1} A0(t, i) * A0(t, j)

    RDom t(0, n, "t");
    B(j, i) = cast<num_t>(0);
    B(j, i) += A0(t, i) * A0(t, j);

    // ---------------------------
    // Schedule for initialization
    // ---------------------------
    //
    // B is a dense Gram matrix; each (j,i) is independent, so we can
    // parallelize across rows and vectorize across the reduction dim t.

    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());

    // Compute the whole matrix at once, parallelizing over rows (i).
    B.compute_root()
        .parallel(i);

    // For the reduction update over t, split t into a vectorized inner loop.
    RVar t_outer("t_outer"), t_inner("t_inner");
    B.update()
        .parallel(i)
        .split(t, t_outer, t_inner, vec)
        .vectorize(t_inner);

    // Realize B directly into the provided buffer A. This is equivalent
    // to computing B and then copying B into A as in the original C code.
    B.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Matrix A: original C is DATA_TYPE A[N][N];
    // We map to Halide Buffer with shape (cols, rows) = (n, n)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Translate kernel_lu into Halide-assisted code.
    //
    // Original C kernel:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < n; j++) {
    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // This algorithm has loop-carried dependencies along i and j, so we cannot
    // express the full kernel as a single pure Halide Func. Instead, we:
    //
    //   - Keep the outer loops over i and j on the host (as required to
    //     preserve the sequential dependencies).
    //   - Use Halide Funcs to compute the inner summations over k:
    //       L-part, for j < i:  sum_{k<j} A[i][k] * A[k][j]
    //       U-part, for j >= i: sum_{k<i} A[i][k] * A[k][j]
    //
    //   - We use ImageParam + Param<int> for i and j, and realize either a
    //     scalar Func (for L) or a whole row (for U) where needed.
    //
    // Compared to the naive per-(i,j) scalar realization, we optimize the
    // U-part by computing the entire row j = 0..n-1 for a fixed i in one
    // Halide call, which improves locality and amortizes scheduling overhead.
    // -------------------------------------------------------------------------

    // ImageParam representing the current matrix A; note that we never write
    // to A inside Halide; we only read from it in the Funcs below. The
    // in-place updates to A are done on the host after each realization.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameters for the current (i, j) indices
    Param<int> i_param("i");
    Param<int> j_param("j");

    // ---------------------------------------------------------------------
    // L-part: scalar Func that computes
    //   A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[k][j]
    // for j < i, before dividing by A[j][j].
    //
    // A[i][j] in C corresponds to A_param(j_param, i_param) in Halide.
    // ---------------------------------------------------------------------
    Func left_elem("left_elem");
    {
        // Base value A[i][j]
        left_elem() = A_param(j_param, i_param);

        // Reduction over k = 0 .. j-1:
        // A[i][j] -= A[i][k] * A[k][j]
        //
        // A[i][k] -> A_param(k, i_param)
        // A[k][j] -> A_param(j_param, k)
        RDom k_left(0, j_param, "k_left");
        left_elem() += cast<num_t>(-1) *
                       A_param(k_left, i_param) *
                       A_param(j_param, k_left);
    }

    // ---------------------------------------------------------------------
    // U-part: row Func that computes, for a fixed i,
    //
    //   right_row(j) = A[i][j] - sum_{k=0}^{i-1} A[i][k] * A[k][j]
    //
    // for all 0 <= j < n in a single realization. We only *use*
    // the entries with j >= i, but computing the full row allows
    // Halide to vectorize/parallelize across j if desired.
    //
    // A[i][j] -> A_param(j, i_param)
    // A[i][k] -> A_param(k, i_param)
    // A[k][j] -> A_param(j, k)
    // ---------------------------------------------------------------------
    Var jj("jj");
    Func right_row("right_row");
    {
        // Base row A[i][j]
        right_row(jj) = A_param(jj, i_param);

        // Reduction over k = 0 .. i-1:
        RDom k_right(0, i_param, "k_right");
        right_row(jj) += cast<num_t>(-1) *
                         A_param(k_right, i_param) *
                         A_param(jj, k_right);
    }

    // --------------------
    // Schedules for kernel
    // --------------------

    // Both left_elem and right_row are small pipelines that will be
    // called many times, so we JIT-compile them once and reuse.
    left_elem.compute_root();
    right_row.compute_root();

    left_elem.compile_jit();
    right_row.compile_jit();

    // -------------------------------------------------------------------------
    // Run kernel and time it
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // Bind the row index once per i
        i_param.set(i);

        // -------------------------------------------------------------
        // First inner loop: j = 0 .. i-1 (L-part).
        //
        // This loop has loop-carried dependencies along j, so we keep
        // it scalar on the host and use a scalar Halide reduction only
        // for the inner k-loop.
        // -------------------------------------------------------------
        for (int j = 0; j < i; j++) {
            j_param.set(j);

            // Compute A[i][j] - sum_{k<j} A[i][k] * A[k][j]
            Halide::Buffer<num_t> tmp = left_elem.realize();
            num_t val = tmp();  // zero-dimensional buffer

            // Divide by A[j][j]
            // Mapping: A[j][j] in C -> A(j, j) in Halide
            val /= A(j, j);

            // Store back into A[i][j] (i.e. A(j, i) in Halide)
            A(j, i) = val;
        }

        // -------------------------------------------------------------
        // Second inner loop: j = i .. n-1 (U-part).
        //
        // Here there are no dependencies across j: for a fixed i,
        // every A[i][j] with j >= i uses the same set of k = 0..i-1.
        // We exploit this by computing the entire row in one Halide
        // realization and then copying the needed part back to A.
        // -------------------------------------------------------------

        // Compute the full row right_row(j) for this i.
        Halide::Buffer<num_t> row_buf = right_row.realize({n});

        // Copy back only j >= i, preserving the original C semantics.
        for (int j = i; j < n; j++) {
            // A[i][j] in C corresponds to A(j, i) in Halide
            A(j, i) = row_buf(j);
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
