// Array initialization: translate Polybench init_array() into a Halide pipeline
// -----------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // We map the original C array A[i][j] to Halide buffer A(j, i):
    //   - i is the row index  -> second dimension (y)
    //   - j is the column index -> first dimension (x)

    Var i("i"), j("j");
    Func A0("A0"), B("B");

    // First, generate the lower-triangular matrix used as in the C code:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Note: for 0 <= j < n, (-j % n) == -j, so we can drop the % n.
    // We fold all this into a single expression:

    Expr one   = cast<num_t>(1);
    Expr zero  = cast<num_t>(0);
    Expr n_val = cast<num_t>(n);

    A0(j, i) = select(
        j <= i,
        // On or below the diagonal
        select(i == j,
               // Diagonal element
               one,
               // Strictly lower triangular part
               cast<num_t>(-j) / n_val + one),
        // Above the diagonal
        zero);

    // Now make the matrix positive semi-definite by computing:
    //
    // B[r][s] = sum_t A[r][t] * A[s][t];
    //
    // and then copying B back into A. In terms of our mapping:
    // B(r, s) in C  -> B(j, i) in Halide
    // A[r][t]       -> A0(t, r) -> A0(t, i)
    // A[s][t]       -> A0(t, s) -> A0(t, j)
    //
    // So:
    //   B(j, i) = sum_{t=0..n-1} A0(t, i) * A0(t, j)

    RDom t(0, n, "t");
    B(j, i) = cast<num_t>(0);
    B(j, i) += A0(t, i) * A0(t, j);

    // ----------------------------
    // Scheduling for better speed
    // ----------------------------
    //
    // This initialization is O(n^3) in compute, so it is worthwhile to:
    //   - Precompute A0 once (O(n^2)) and store it.
    //   - Parallelize over rows of B.
    //   - Vectorize across columns of B.
    //
    // This improves data locality and uses all cores during init.

    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) {
        vec_width = 1;
    }

    // A0 is purely pointwise, so we can compute it once and reuse it.
    A0.compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Compute B at the root, parallelized across rows (i) and
    // vectorized across columns (j). Apply the same schedule to
    // both the pure and update definitions.
    B.compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    B.update()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize B directly into the provided buffer A. This is equivalent
    // to computing B and then copying B into A as in the original C code.
    B.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Matrix A: original C is DATA_TYPE A[N][N];
    // We map to Halide Buffer with shape (cols, rows) = (n, n)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Translate kernel_lu into Halide-assisted code.
    //
    // Original C kernel:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < n; j++) {
    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // This algorithm has loop-carried dependencies along i and j, so we cannot
    // express the full kernel as a single pure Halide Func. Instead, we:
    //
    //   - Keep the outer loops over i and j on the host (as required to
    //     preserve the sequential dependencies).
    //   - Use Halide Funcs to compute each inner summation over k:
    //       sum_{k<j} A[i][k] * A[k][j]
    //       sum_{k<i} A[i][k] * A[k][j]
    //
    //   - We use ImageParam + Param<int> for i and j, and realize a small
    //     one-dimensional Func for each (i, j) where needed.
    //
    // The main performance problem in a naive translation is per-element
    // dynamic allocation when realizing 0-dimensional Funcs. Below we
    // structure the Funcs as 1D of extent 1 and reuse the same tiny
    // Buffers across all calls, eliminating per-(i,j) heap traffic while
    // still letting Halide generate the reduction loops over k.
    // -------------------------------------------------------------------------

    // ImageParam representing the current matrix A; note that we never write
    // to A inside Halide; we only read from it in the Funcs below. The
    // in-place updates to A are done on the host after each scalar realization.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameters for the current (i, j) indices
    Param<int> i_param("i");
    Param<int> j_param("j");

    // Dummy Var used to make the Funcs 1D of size 1. This allows us to
    // realize into a reused 1-element Buffer instead of allocating a
    // new 0-dim Buffer on every call.
    Var d("d");

    // Func to compute A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[k][j]
    // for the case j < i (the "L" part), before dividing by A[j][j].
    Func left_elem("left_elem");
    {
        // A[i][j] in C corresponds to A_param(j_param, i_param)
        left_elem(d) = A_param(j_param, i_param);

        // Sum over k = 0 .. j-1:
        // A[i][j] -= A[i][k] * A[k][j]
        //
        // A[i][k] -> A_param(k,      i_param)
        // A[k][j] -> A_param(j_param, k)
        RDom k_left(0, j_param, "k_left");
        left_elem(d) += cast<num_t>(-1) *
                        A_param(k_left, i_param) *
                        A_param(j_param, k_left);
    }

    // Func to compute A[i][j] - sum_{k=0}^{i-1} A[i][k] * A[k][j]
    // for the case j >= i (the "U" part).
    Func right_elem("right_elem");
    {
        right_elem(d) = A_param(j_param, i_param);

        // Sum over k = 0 .. i-1:
        // A[i][j] -= A[i][k] * A[k][j]
        //
        // A[i][k] -> A_param(k,      i_param)
        // A[k][j] -> A_param(j_param, k)
        RDom k_right(0, i_param, "k_right");
        right_elem(d) += cast<num_t>(-1) *
                         A_param(k_right, i_param) *
                         A_param(j_param, k_right);
    }

    // (Optional) We could add schedules such as:
    //
    //   left_elem.update().vectorize(k_left, 8);
    //   right_elem.update().vectorize(k_right, 8);
    //
    // to vectorize the reductions over k. This can slightly change
    // floating-point roundoff vs. strictly scalar code, so we keep
    // the default scalar-like schedule here to preserve strict
    // evaluation order.

    // JIT-compile the scalar pipelines once; we will reuse them for all (i, j).
    Target kernel_target = get_jit_target_from_environment();
    left_elem.compile_jit(kernel_target);
    right_elem.compile_jit(kernel_target);

    // Reusable 1-element buffers to hold the scalar results from
    // left_elem and right_elem. This avoids per-call heap allocations.
    Halide::Buffer<num_t> left_buf(1);
    Halide::Buffer<num_t> right_buf(1);

    // -------------------------------------------------------------------------
    // Run kernel and time it
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        i_param.set(i);

        // First inner loop: j = 0 .. i-1  (compute L part)
        for (int j = 0; j < i; j++) {
            j_param.set(j);

            // Compute A[i][j] - sum_{k<j} A[i][k] * A[k][j]
            left_elem.realize(left_buf);
            num_t val = left_buf(0);  // single element

            // Divide by A[j][j]
            // Mapping: A[j][j] in C -> A(j, j) in Halide
            val /= A(j, j);

            // Store back into A[i][j] (i.e. A(j, i) in Halide)
            A(j, i) = val;
        }

        // Second inner loop: j = i .. n-1  (compute U part)
        for (int j = i; j < n; j++) {
            j_param.set(j);

            // Compute A[i][j] - sum_{k<i} A[i][k] * A[k][j]
            right_elem.realize(right_buf);
            num_t val = right_buf(0);  // single element

            // Store back into A[i][j] (no division here)
            A(j, i) = val;
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
