// include benchmark-specific definitions
#include "lu.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -----------------------------------------------------------------------------
// Array initialization: translate Polybench init_array() into a Halide pipeline
// -----------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // We map the original C array A[i][j] to Halide buffer A(j, i):
    //   - i is the row index    -> second dimension (y)
    //   - j is the column index -> first dimension (x)

    Var x("x"), y("y");
    Func A0("A0"), B("B");

    // First, generate the lower-triangular matrix used as in the C code:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Note: for 0 <= j < n, (-j % n) == -j, so we can drop the % n.
    //
    // With our mapping (x = j, y = i), this becomes:
    //   A0(x, y) = 1                        if x == y  (diagonal)
    //              (-x)/n + 1               if x <  y  (strictly lower)
    //              0                        if x >  y  (upper part)

    Expr one   = cast<num_t>(1);
    Expr zero  = cast<num_t>(0);
    Expr n_val = cast<num_t>(n);

    A0(x, y) = select(
        x <= y,
        // On or below the diagonal
        select(
            x == y,
            // Diagonal element
            one,
            // Strictly lower triangular part
            cast<num_t>(-x) / n_val + one),
        // Above the diagonal
        zero);

    // Now make the matrix positive semi-definite by computing:
    //
    // B[r][s] = sum_t A[r][t] * A[s][t];
    //
    // and then copying B back into A. In terms of our mapping:
    // B(r, s) in C  -> B(x, y) in Halide
    // A[r][t]       -> A0(t, r) -> A0(t, y)
    // A[s][t]       -> A0(t, s) -> A0(t, x)
    //
    // So:
    //   B(x, y) = sum_{t=0..n-1} A0(t, y) * A0(t, x)

    RDom t(0, n, "t");
    B(x, y) = cast<num_t>(0);
    B(x, y) += A0(t, y) * A0(t, x);

    // -------------------------------
    // Schedule for initialization
    // -------------------------------
    // We compute B (and therefore A0) in a cache-friendly, parallel way:
    //
    // - B is computed at root.
    // - Parallelize across rows (y).
    // - Vectorize across columns (x).
    //
    // This gives us good multi-core utilization and SIMD usage while
    // still keeping the code simple and robust for arbitrary N.

    const int vec_width = 8;  // reasonable default for typical x86 AVX/SSE

    B.compute_root()
        .parallel(y)
        .vectorize(x, vec_width);

    B.update()
        .parallel(y)
        .vectorize(x, vec_width);

    // Realize B directly into the provided buffer A. This is equivalent
    // to computing B and then copying B into A as in the original C code.
    B.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Matrix A: original C is DATA_TYPE A[N][N];
    // We map to Halide Buffer with shape (cols, rows) = (n, n)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Translate kernel_lu into Halide-assisted code.
    //
    // Original C kernel:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < n; j++) {
    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // This algorithm has loop-carried dependencies along i and j, so we cannot
    // express the full kernel as a single pure Halide Func. Following the
    // recommended pattern for such dynamic-programming style computations:
    //
    //   - Keep the outer loops over i and j on the host (to preserve
    //     sequential dependencies).
    //   - Use Halide Funcs to compute the inner summations over k:
    //       sum_{k<j} A[i][k] * A[k][j]   (L-part)
    //       sum_{k<i} A[i][k] * A[k][j]   (U-part)
    //
    //   - The matrix A is updated in-place on the host. Inside Halide we only
    //     read from A via an ImageParam; because the ImageParam points to the
    //     same underlying Buffer, we always see the most recent in-place
    //     updates.
    // -------------------------------------------------------------------------

    // ImageParam representing the current matrix A; we only ever *read* A
    // inside Halide. All in-place writes happen on the host.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameters for the current (i, j) indices
    Param<int> i_param("i");
    Param<int> j_param("j");

    // -------------------------------------------------------------------------
    // 1) Scalar Func for the L-part:
    //
    //     left_elem(i,j) = A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[k][j]
    //
    // This matches the first inner loop (j < i) before division by A[j][j].
    // We keep this scalar version because of the true dependence along j.
    // -------------------------------------------------------------------------
    Func left_elem("left_elem");
    {
        // A[i][j] in C corresponds to A_param(j_param, i_param)
        left_elem() = A_param(j_param, i_param);

        // Sum over k = 0 .. j-1:
        // A[i][j] -= A[i][k] * A[k][j]
        //
        // Mapping:
        // A[i][k] -> A_param(k,         i_param)
        // A[k][j] -> A_param(j_param,   k)
        RDom k_left(0, j_param, "k_left");
        left_elem() += -A_param(k_left, i_param) * A_param(j_param, k_left);
    }

    // -------------------------------------------------------------------------
    // 2) Row-wise Func for the U-part:
    //
    // For each fixed i, and j in [i, n):
    //
    //     A[i][j] <- A[i][j] - sum_{k=0}^{i-1} A[i][k] * A[k][j]
    //
    // Rather than computing a scalar for each (i,j), we compute the entire
    // row segment j = i..n-1 in one Halide call:
    //
    //   - We introduce a local index jj = j - i, so that jj runs from 0 to
    //     (n - i - 1). Actual column index is:
    //
    //         j = i + jj
    //
    //   - This lets us exploit SIMD and multi-core parallelism across jj,
    //     while preserving the exact original arithmetic for each A[i][j].
    // -------------------------------------------------------------------------
    Var jj("jj");
    Func row_u("row_u");
    {
        // Absolute column index as an Expr
        Expr j_abs = i_param + jj;  // j = i + jj

        // Initial value A[i][j]
        // C: A[i][j] -> Halide: A_param(j_abs, i_param)
        row_u(jj) = A_param(j_abs, i_param);

        // Reduction over k = 0 .. i-1 (independent of j):
        //   row_u(jj) -= A[i][k] * A[k][j]
        //
        // C mapping:
        //   A[i][k] -> A_param(k,      i_param)
        //   A[k][j] -> A_param(j_abs,  k)
        RDom k_u(0, i_param, "k_u");
        row_u(jj) += -A_param(k_u, i_param) * A_param(j_abs, k_u);
    }

    // -------------------------------
    // Schedule for row_u (U-part row)
    // -------------------------------
    // row_u is evaluated row-by-row (one fixed i per host iteration),
    // but within a row we:
    //
    //   - Vectorize across jj (columns).
    //   - Vectorize both the pure and update stages for better SIMD usage.
    //
    const int vec_width_u = 8;  // tuned for typical AVX/SSE-capable CPUs

    row_u.compute_root();
    row_u.vectorize(jj, vec_width_u);
    row_u.update().vectorize(jj, vec_width_u);

    // JIT-compile the pipelines once; we will reuse them for all (i, j).
    left_elem.compile_jit();
    row_u.compile_jit();

    // Temporary buffer to hold an entire U-part row segment for each i.
    // We allocate once at full size and use cropped views (0 .. n-i-1)
    // when realizing row_u.
    Halide::Buffer<num_t> row_u_buf(n);

    // -------------------------------------------------------------------------
    // Run kernel and time it
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // Current row index for all Halide computations in this iteration
        i_param.set(i);

        // -------------------------------------------------------------
        // First inner loop: L-part, j = 0 .. i-1
        // -------------------------------------------------------------
        for (int j = 0; j < i; j++) {
            j_param.set(j);

            // Compute A[i][j] - sum_{k<j} A[i][k] * A[k][j]
            Halide::Buffer<num_t> tmp = left_elem.realize();
            num_t val = tmp();  // zero-dimensional buffer (scalar)

            // Divide by A[j][j]
            // Mapping: A[j][j] in C -> A(j, j) in Halide
            val /= A(j, j);

            // Store back into A[i][j] (i.e. A(j, i) in Halide)
            A(j, i) = val;
        }

        // -------------------------------------------------------------
        // Second inner loop: U-part, j = i .. n-1
        //
        // We compute the entire row segment j = i..n-1 in one Halide
        // call row_u(jj), where jj = j - i, 0 <= jj < (n - i).
        // -------------------------------------------------------------
        int width = n - i;
        if (width > 0) {
            // Create a view of row_u_buf covering indices [0, width)
            Halide::Buffer<num_t> sub = row_u_buf.cropped(/*dim=*/0, /*min=*/0, /*extent=*/width);

            // Realize the U-part row segment for this i
            row_u.realize(sub);

            // Copy results back into the in-place matrix A.
            // Recall:
            //   jj = j - i  -> j = i + jj
            //   A[i][j] in C -> A(j, i) in Halide
            for (int jj_val = 0; jj_val < width; ++jj_val) {
                int j = i + jj_val;
                A(j, i) = sub(jj_val);
            }
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
