    // locality matter. We:
    //  - Materialize A0 once (compute_root), instead of recomputing
    //    its simple formula inside the reduction.
    //  - Parallelize over rows (i), which are independent.
    //  - Vectorize along the innermost x dimension (j), which is
    //    contiguous in memory.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // A0: n x n, computed once, row-parallel and vectorized across columns.
    A0.compute_root()
       .parallel(i)
       .vectorize(j, vec_width);

